INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Réussir ses photos au téléphone pour sa fiche Google et ses réseaux', 'photos-telephone', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Pas besoin d''un photographe pour chaque publication. Préparer la prise de vue, six gestes pour une photo nette, retoucher sans tricher et respecter le droit à l''image.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un téléphone récent suffit pour des photos de qualité professionnelle. La lumière, le cadrage et la netteté comptent plus que l''appareil.</li> <li>Photographiez à la lumière du jour, objectif nettoyé, sans zoom numérique, et faites plusieurs prises de chaque sujet.</li> <li>Une personne reconnaissable sur la photo doit avoir donné son accord écrit avant la publication.</li> </ul> </div> <p>Vos plats, vos chantiers, votre boutique : ce sont vos meilleures publicités. Pourtant, beaucoup de fiches Google et de pages Facebook affichent des photos sombres, floues ou de travers, qui donnent une mauvaise image d''un travail pourtant soigné.</p> <p>Pas besoin d''un photographe pour chaque publication. Avec quelques réflexes, le téléphone que vous avez en poche fait l''affaire. Voici la méthode, de la prise de vue à la mise en ligne.</p> <h2>Préparer la prise de vue</h2> <ol class="etapes"> <li><strong>Nettoyez l''objectif.</strong> Un objectif gras, touché toute la journée, donne une image voilée. Un coup de chiffon doux suffit.</li> <li><strong>Choisissez la lumière du jour.</strong> Près d''une fenêtre à l''intérieur, ou dehors à l''ombre. Évitez le plein soleil de midi, qui écrase les couleurs et crée des ombres dures, et le flash, qui aplatit tout.</li> <li><strong>Rangez le décor.</strong> Retirez ce qui n''a rien à faire dans l''image : sacs, câbles, poubelle, voiture garée devant la vitrine.</li> <li><strong>Activez la grille de l''appareil photo</strong> dans les réglages. Elle aide à garder l''horizon droit et à placer le sujet.</li> </ol> <h2>Prendre la photo en 6 gestes</h2> <ol class="etapes"> <li><strong>Touchez l''écran sur le sujet</strong> pour faire la mise au point, puis baissez légèrement la luminosité si le ciel ou un fond blanc est « brûlé ».</li> <li><strong>Avancez plutôt que zoomer.</strong> Le zoom numérique dégrade l''image. Si le téléphone a plusieurs objectifs (x2, x3), utilisez-les, sinon rapprochez-vous.</li> <li><strong>Tenez le téléphone à deux mains</strong>, coudes contre le corps, ou posez-le sur un appui. La plupart des photos floues viennent d''un bougé.</li> <li><strong>Changez d''angle.</strong> Un plat se photographie souvent de dessus ou à hauteur d''assiette ; une façade, de face et droite ; un produit, en gros plan sur un détail.</li> <li><strong>Faites plusieurs prises</strong> de chaque sujet, en format horizontal et vertical. Vous choisirez au calme, et le vertical servira pour les stories et les vidéos.</li> <li><strong>Montrez le vrai.</strong> Une équipe au travail, un chantier avant et après, la vitrine à l''ouverture : les clients font plus confiance à une photo authentique qu''à une image de banque d''images.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une boulangerie à Saint-Joseph</p> <p>Le gérant photographiait ses pains le soir, sous les néons, avec le flash. Il change d''heure : chaque matin à 7 h, il pose une fournée sur le comptoir près de la vitrine, nettoie l''objectif, prend trois photos de dessus et trois de côté. Il garde les deux meilleures pour sa fiche Google et Facebook, sans filtre, juste en redressant l''image.</p> </div> <h2>Retoucher sans tricher</h2> <p>L''outil de retouche intégré au téléphone suffit : recadrer, redresser, éclaircir légèrement. Évitez les filtres marqués. Google demande, pour les photos d''une fiche d''établissement, une image nette, bien éclairée et fidèle à la réalité, sans retouches importantes ni filtres excessifs.</p> <table class="table-article"> <thead><tr><th>Usage</th><th>Format conseillé</th><th>À retenir</th></tr></thead> <tbody> <tr><td>Fiche Google</td><td>JPG ou PNG, de 10 Ko à 5 Mo</td><td>Google recommande 720 × 720 pixels, et au minimum 250 × 250</td></tr> <tr><td>Publication sur les réseaux</td><td>Carré ou vertical</td><td>Le vertical occupe plus de place sur l''écran d''un téléphone</td></tr> <tr><td>Site internet</td><td>Redimensionnée à la taille d''affichage</td><td>Une photo trop lourde ralentit la page : voir <a href="/blog/accelerer-son-site">accélérer son site</a></td></tr> </tbody> </table> <h2>Le droit à l''image</h2> <p>Dès qu''une personne est reconnaissable sur une photo, il faut son accord écrit pour la publier, rappelle Service-Public.fr. Pour un mineur, c''est l''accord des parents. Cela vaut pour vos salariés comme pour vos clients : un simple formulaire signé, conservé avec la photo, suffit à vous protéger.</p> <ul class="checklist"> <li>Le sujet est net, et la photo prise à la lumière du jour.</li> <li>L''horizon est droit, le décor rangé.</li> <li>Pas de filtre qui change les couleurs réelles du produit.</li> <li>Les personnes reconnaissables ont donné leur accord écrit.</li> <li>La photo est enregistrée dans un dossier partagé, rangé par mois, pour la réutiliser.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Les contenus pour les réseaux sociaux sont préparés et planifiés chaque mois, à partir de 290 € par mois pour 8 publications. Le diagnostic gratuit permet de voir ce que vous pouvez faire vous-même et ce qui vaut la peine d''être confié.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il acheter un meilleur téléphone ?</h3> <p>Rarement. Un téléphone de moins de cinq ans, bien utilisé, donne des photos tout à fait correctes pour le web. La lumière et la stabilité font plus de différence que le modèle.</p> <h3>Puis-je utiliser des photos trouvées sur internet ?</h3> <p>Non, sauf si leur licence l''autorise clairement. Une photo trouvée sur Google appartient à son auteur. Et pour votre fiche Google, des photos réelles de votre établissement inspirent bien plus confiance.</p> <h3>Combien de photos publier sur ma fiche Google ?</h3> <p>Il n''y a pas de nombre imposé. Commencez par le logo, une photo de couverture, l''extérieur pour être reconnu, l''intérieur et vos produits ou réalisations, puis ajoutez-en régulièrement. Voir notre guide de la <a href="/blog/fiche-google-reunion">fiche Google</a>.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/6103862?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : ajouter des photos et des vidéos</a>.</li> <li><a href="https://www.service-public.fr/particuliers/vosdroits/F32103" target="_blank" rel="noopener">Service-Public.fr : droit à l''image et respect de la vie privée</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Réussir ses photos au téléphone : la méthode', 'Lumière, cadrage, netteté, retouche sans filtre et droit à l''image : la méthode pour prendre de bonnes photos d''entreprise avec son téléphone.', 'photo téléphone entreprise, photos fiche Google, photo réseaux sociaux, droit à l''image, photo produit smartphone', '/assets/images/blog/photos-telephone.webp', '/assets/images/blog/photos-telephone.webp', 'draft', NOW(), NOW(), 'pas-a-pas')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Vidéos courtes au téléphone : tourner un Reel ou un TikTok pour son entreprise', 'videos-courtes-telephone', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Reels, TikTok, Shorts : une vidéo verticale de quelques secondes suffit pour montrer votre savoir-faire. Les réglages, six étapes de tournage et dix idées de vidéos.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une vidéo courte se tourne au téléphone, à la verticale, en moins d''une minute. Le message doit être compris dans les premières secondes.</li> <li>La méthode tient en quatre temps : une idée par vidéo, un plan de tournage sur une feuille, un son propre, un montage simple avec sous-titres.</li> <li>Utilisez les musiques proposées par l''application plutôt qu''une chanson du commerce, et demandez l''accord écrit des personnes filmées.</li> </ul> </div> <p>Reels sur Instagram et Facebook, TikTok, Shorts sur YouTube : les vidéos verticales de quelques secondes occupent une grande partie des fils d''actualité. Pour une petite entreprise, c''est une occasion de montrer son savoir-faire sans budget de tournage.</p> <p>Le frein, souvent, c''est de ne pas savoir par où commencer. Voici une méthode simple, avec le téléphone que vous avez déjà, pour sortir une première vidéo propre en une heure.</p> <h2>Les réglages à faire une fois</h2> <table class="table-article"> <thead><tr><th>Réglage</th><th>Pourquoi</th></tr></thead> <tbody> <tr><td>Filmer à la verticale (format 9:16)</td><td>C''est le format plein écran des téléphones et des réseaux de vidéos courtes</td></tr> <tr><td>Résolution 1080p, 30 images par seconde</td><td>Une bonne qualité, avec des fichiers raisonnables à envoyer</td></tr> <tr><td>Grille activée</td><td>Pour garder les lignes droites et cadrer le sujet</td></tr> <tr><td>Mode avion ou « Ne pas déranger »</td><td>Pour qu''un appel ne coupe pas la prise</td></tr> </tbody> </table> <h2>Tourner une vidéo en 6 étapes</h2> <ol class="etapes"> <li><strong>Une idée, une vidéo.</strong> Un geste de métier, une question de client, un avant-après, une nouveauté. Si vous ne pouvez pas résumer la vidéo en une phrase, elle est trop chargée.</li> <li><strong>Écrivez le plan sur une feuille</strong> : la phrase d''accroche des premières secondes, trois ou quatre plans, la conclusion (« Réservez au… », « Passez nous voir à… »).</li> <li><strong>Soignez le son.</strong> Filmez au calme, près du téléphone, ou avec un petit micro-cravate. Une image moyenne passe, un son inaudible fait décrocher.</li> <li><strong>Stabilisez l''image.</strong> Posez le téléphone sur un support ou un trépied, et bougez lentement. Filmez chaque plan quelques secondes de plus que nécessaire, pour avoir de la marge au montage.</li> <li><strong>Montez simplement</strong> avec l''éditeur de l''application ou un éditeur gratuit : coupez les temps morts, gardez les plans courts, ajoutez des sous-titres. Beaucoup de vidéos sont regardées sans le son.</li> <li><strong>Publiez avec un texte utile</strong> : une phrase qui dit ce qu''on voit, le lieu, et un appel à l''action. Publiez le même fichier sur les réseaux où sont vos clients.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un atelier de réparation de vélos à Saint-Paul</p> <p>Le mécanicien filme, téléphone posé sur l''établi, le changement d''une chambre à air en quatre plans : la roue crevée, le démontage, le remontage, le vélo qui repart. En accroche, un texte à l''écran : « Crevé ? 10 minutes à l''atelier ». Il ajoute des sous-titres, une musique de la bibliothèque de l''application, et termine sur l''adresse de l''atelier.</p> </div> <h2>Musique et personnes filmées</h2> <p>Une chanson du commerce ajoutée au montage n''est pas libre de droits : la vidéo peut être rendue muette ou retirée. Utilisez les sons proposés dans l''application au moment de publier, ou une musique libre dont la licence autorise l''usage commercial.</p> <p>Pour les personnes reconnaissables à l''image, salariés comme clients, la règle est la même que pour une photo : il faut leur accord écrit avant la diffusion, et celui des parents pour un mineur, comme le rappelle Service-Public.fr.</p> <h2>Dix idées de vidéos pour démarrer</h2> <ul class="checklist"> <li>Un geste de votre métier, filmé de près.</li> <li>Un avant-après (chantier, coiffure, nettoyage, jardin).</li> <li>La réponse à une question que les clients posent souvent.</li> <li>La présentation d''un membre de l''équipe.</li> <li>L''ouverture de la boutique le matin.</li> <li>Un nouveau produit, montré en main.</li> <li>Une erreur fréquente à éviter, et la bonne façon de faire.</li> <li>Les coulisses d''une préparation (cuisine, atelier, livraison).</li> <li>Un conseil de saison (cyclone, rentrée, fêtes de fin d''année).</li> <li>Le trajet pour venir chez vous, en quelques plans.</li> </ul> <p>D''autres idées dans notre article <a href="/blog/idees-publications-reseaux-sociaux">30 idées de publications pour les réseaux sociaux</a>.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Une vidéo courte au format Reel, TikTok ou Short coûte 190 €. L''offre premium de contenus pour les réseaux sociaux, à 690 € par mois, comprend 20 publications dont des vidéos courtes.</p> <p><a href="/tarifs" class="encadre-lien">Voir les tarifs</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quelle durée viser ?</h3> <p>Les plateformes acceptent des vidéos plus longues, mais pour une petite entreprise, 15 à 45 secondes suffisent souvent. Ce qui compte, c''est d''accrocher dans les premières secondes et de ne garder que l''utile.</p> <h3>Faut-il se montrer face caméra ?</h3> <p>Ce n''est pas obligatoire. Les mains au travail, le produit ou le lieu suffisent. Mais un visage et une voix créent souvent plus de confiance, surtout pour un service.</p> <h3>Puis-je mettre une vidéo sur ma fiche Google ?</h3> <p>Oui. Google accepte sur la fiche d''établissement des vidéos de 30 secondes au maximum, jusqu''à 75 Mo et d''une résolution d''au moins 720p.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/6103862?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : ajouter des photos et des vidéos</a>.</li> <li><a href="https://www.service-public.fr/particuliers/vosdroits/F32103" target="_blank" rel="noopener">Service-Public.fr : droit à l''image et respect de la vie privée</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Vidéos courtes au téléphone : la méthode simple', 'Réglages, plan de tournage, son, montage et sous-titres : la méthode pour tourner une vidéo courte d''entreprise au téléphone, et dix idées pour démarrer.', 'vidéo courte entreprise, tourner un Reel, vidéo TikTok entreprise, montage vidéo téléphone, idées de vidéos', '/assets/images/blog/videos-courtes-telephone.webp', '/assets/images/blog/videos-courtes-telephone.webp', 'draft', NOW(), NOW(), 'pas-a-pas')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Choisir son CRM : tableur, outil simple ou logiciel complet ?', 'choisir-crm', (SELECT id FROM service_categories WHERE slug = 'crm'), 'CRM', 'Les demandes de devis se perdent entre téléphone, e-mails et Messenger ? Les quatre familles de CRM comparées, six questions pour choisir et les règles de conservation de la CNIL.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un CRM est un fichier clients organisé : qui sont vos contacts, où en est chaque demande, quand relancer. Un tableur peut suffire au début.</li> <li>Choisissez selon votre besoin réel : le nombre de contacts, le nombre de personnes qui s''en servent, et ce que vous voulez automatiser.</li> <li>Quel que soit l''outil, le RGPD s''applique : la CNIL admet de garder les données d''un prospect trois ans après le dernier contact venant de lui.</li> </ul> </div> <p>Les demandes de devis arrivent par téléphone, par Messenger, par e-mail, sur un bout de papier au comptoir. Certaines sont oubliées, d''autres relancées deux fois. Et quand un salarié part en congé, personne ne sait où en est le dossier.</p> <p>Un CRM (gestion de la relation client) range tout au même endroit. Mais entre le tableur, l''application gratuite et le logiciel complet, le choix n''est pas évident. Ce comparatif vous aide à choisir le bon niveau, sans payer pour des fonctions que vous n''utiliserez pas.</p> <h2>Les quatre familles de solutions</h2> <table class="table-article"> <thead><tr><th>Solution</th><th>Pour qui</th><th>Points forts</th><th>Limites</th></tr></thead> <tbody> <tr><td>Tableur partagé</td><td>Une ou deux personnes, quelques dizaines de demandes par mois</td><td>Gratuit, connu de tous, rapide à mettre en place</td><td>Pas de rappels automatiques, erreurs de saisie, difficile à plusieurs</td></tr> <tr><td>CRM simple (offre gratuite ou d''entrée de gamme)</td><td>TPE qui veut suivre ses devis et ses relances</td><td>Suivi des affaires par étapes, rappels, application mobile</td><td>Fonctions avancées payantes, données souvent hébergées hors de France</td></tr> <tr><td>CRM complet</td><td>Équipe commerciale de plusieurs personnes</td><td>Automatisations, e-mails, statistiques, intégrations</td><td>Plus cher, plus long à paramétrer, risque de sous-utilisation</td></tr> <tr><td>Logiciel métier avec module client</td><td>Métiers avec un outil dédié (restauration, santé, bâtiment, beauté)</td><td>Clients, rendez-vous, devis et factures au même endroit</td><td>Fonctions marketing souvent limitées</td></tr> </tbody> </table> <h2>Les questions à se poser avant de choisir</h2> <ol class="etapes"> <li><strong>Que voulez-vous suivre ?</strong> Des demandes de devis, des rendez-vous, des clients réguliers, des ventes en ligne ? Écrivez les étapes de votre parcours client : demande, devis envoyé, relance, signé ou perdu.</li> <li><strong>Qui va s''en servir ?</strong> Un outil que l''équipe trouve compliqué ne sera pas rempli. Faites tester la version d''essai à ceux qui saisiront les données.</li> <li><strong>D''où viennent les contacts ?</strong> Formulaire du site, téléphone, réseaux sociaux. Vérifiez que l''outil peut les recevoir automatiquement, ou qu''une saisie rapide est possible depuis un téléphone.</li> <li><strong>Que voulez-vous automatiser ?</strong> Un rappel de relance, un e-mail de remerciement, une demande d''avis après la prestation. Commencez par une seule automatisation.</li> <li><strong>Où sont les données ?</strong> Lisez les conditions : lieu d''hébergement, possibilité d''exporter vos données dans un fichier si vous changez d''outil, durée d''engagement.</li> <li><strong>Quel coût réel ?</strong> Le prix par utilisateur et par mois, les options payantes, et le temps de mise en place. Comparez sur un an, pas sur le premier mois.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une entreprise de climatisation à Saint-Pierre</p> <p>Deux techniciens et une secrétaire. Les demandes étaient notées dans un cahier, et un devis sur trois n''était jamais relancé. Ils commencent par un tableur partagé avec cinq colonnes : date, contact, besoin, statut, date de relance. Six mois plus tard, avec plus de cinquante demandes par mois, ils passent à un CRM simple qui envoie un rappel de relance au bout de sept jours.</p> </div> <h2>Le RGPD s''applique à tous les outils</h2> <p>Un fichier clients contient des données personnelles. Le référentiel de la CNIL sur la gestion commerciale fixe des repères de conservation pour la prospection :</p> <ul class="checklist"> <li><strong>Clients</strong> : pendant la relation commerciale, puis trois ans après sa fin.</li> <li><strong>Prospects</strong> : trois ans à compter de la collecte ou du dernier contact venant du prospect (une réponse, un clic, pas la simple ouverture d''un e-mail).</li> <li><strong>Après ce délai</strong> : vous pouvez demander à la personne si elle souhaite continuer à recevoir vos offres. Sans réponse positive, supprimez ou archivez ses données.</li> <li><strong>Toujours</strong> : ne collecter que ce qui sert, et informer les personnes de l''usage de leurs données.</li> </ul> <p>Pour l''envoi d''offres par e-mail, voir notre guide <a href="/blog/fideliser-clients">fidéliser ses clients</a>.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''automatisation des relances, des séquences d''e-mails et des tâches répétitives dans votre CRM coûte à partir de 490 €. Le diagnostic gratuit permet de vérifier si un tableur bien tenu suffit encore, ou s''il est temps de passer à un outil.</p> <p><a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Un CRM gratuit suffit-il ?</h3> <p>Souvent, pour démarrer. Vérifiez les limites de l''offre gratuite (nombre de contacts, d''utilisateurs, fonctions bloquées) et la possibilité d''exporter vos données si vous changez d''outil.</p> <h3>Faut-il un CRM si j''ai déjà un logiciel de facturation ?</h3> <p>Pas forcément. Un logiciel de facturation garde les clients, mais rarement les demandes en cours et les relances. Si vous perdez des devis faute de suivi, un CRM ou un tableur de suivi comble ce manque.</p> <h3>Combien de temps pour mettre en place un CRM ?</h3> <p>Pour un outil simple, une journée pour le paramétrer et importer les contacts, puis quelques semaines pour que l''équipe prenne le réflexe de le remplir. Le plus important est de décider qui saisit quoi.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cnil.fr/sites/cnil/files/atoms/files/referentiel_traitements-donnees-caractere-personnel_gestion-activites-commerciales.pdf" target="_blank" rel="noopener">CNIL : référentiel relatif à la gestion des activités commerciales</a>.</li> <li><a href="https://www.cnil.fr/fr/questions-reponses-sur-les-referentiels-relatifs-la-gestion-des-activites-commerciales-et-des" target="_blank" rel="noopener">CNIL : questions-réponses sur les référentiels de gestion commerciale</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Choisir son CRM : le comparatif pour une TPE', 'Tableur, CRM simple, CRM complet ou logiciel métier : comparez les solutions, posez les bonnes questions et respectez le RGPD avant de choisir.', 'choisir un CRM, CRM TPE, CRM gratuit, fichier clients, suivi des devis, RGPD fichier prospects', '/assets/images/blog/choisir-crm.webp', '/assets/images/blog/choisir-crm.webp', 'draft', NOW(), NOW(), 'comparatif')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Fidéliser ses clients : les leviers simples et les règles à respecter', 'fideliser-clients', (SELECT id FROM service_categories WHERE slug = 'crm'), 'CRM', 'Un client satisfait qui ne revient pas, c''est souvent un client qui vous a oublié. Quatre leviers simples, cinq étapes pour les mettre en place et les règles d''envoi par e-mail ou SMS.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un client qui revient coûte moins cher qu''un nouveau client à trouver. La fidélisation commence par un service bien fait, puis par un suivi régulier.</li> <li>Quatre leviers simples : garder le contact, remercier, récompenser la fidélité, demander un avis.</li> <li>Pour écrire à vos clients par e-mail ou SMS, respectez les règles de la CNIL : consentement des particuliers, sauf pour des produits similaires à ceux qu''ils ont déjà achetés, et un désabonnement simple à chaque envoi.</li> </ul> </div> <p>Vous dépensez du temps et de l''argent pour attirer de nouveaux clients : publicité, réseaux sociaux, fiche Google. Pendant ce temps, ceux qui vous connaissent déjà et sont satisfaits ne reviennent pas, simplement parce qu''ils vous ont oublié ou ne savent pas ce que vous proposez d''autre.</p> <p>Fidéliser ne demande pas un programme compliqué. Quelques gestes réguliers suffisent à rester présent dans l''esprit de vos clients. Voici les leviers les plus simples, et les règles à respecter.</p> <h2>Les quatre leviers de la fidélisation</h2> <table class="table-article"> <thead><tr><th>Levier</th><th>Exemples</th><th>Effort</th></tr></thead> <tbody> <tr><td>Garder le contact</td><td>Lettre d''information mensuelle, rappel d''entretien, message pour une nouveauté</td><td>Régulier</td></tr> <tr><td>Remercier</td><td>Message après l''achat, petit mot dans le colis, attention pour un anniversaire de client</td><td>Faible</td></tr> <tr><td>Récompenser</td><td>Carte de fidélité, remise sur la dixième visite, parrainage</td><td>Moyen</td></tr> <tr><td>Écouter</td><td>Demande d''avis, question après la prestation, réponse à chaque remarque</td><td>Faible</td></tr> </tbody> </table> <h2>Mettre en place la fidélisation en 5 étapes</h2> <ol class="etapes"> <li><strong>Rassemblez vos clients dans un seul fichier</strong> : nom, moyen de contact, date du dernier achat, ce qu''ils ont acheté. Un tableur suffit au début. Voir <a href="/blog/choisir-crm">choisir son CRM</a>.</li> <li><strong>Recueillez l''accord pour leur écrire.</strong> Au moment de l''achat ou sur votre site, une case à cocher (jamais pré-cochée) pour recevoir vos offres et nouveautés.</li> <li><strong>Choisissez un rythme tenable.</strong> Un message par mois, utile et court, vaut mieux qu''une série d''offres qui fatigue. Une nouveauté, un conseil de saison, une date à retenir.</li> <li><strong>Prévoyez les messages automatiques</strong> qui reviennent à chaque client : remerciement après l''achat, rappel d''entretien ou de rendez-vous, demande d''avis quelques jours après.</li> <li><strong>Mesurez le retour</strong> : combien de clients reviennent dans l''année, et ce qu''ils achètent. Notez la source quand un client revient après un message.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un garage à Saint-Benoît</p> <p>Le garagiste note la date de chaque vidange dans un tableur, avec l''accord du client pour être prévenu par SMS. Onze mois plus tard, un rappel part : « Votre prochaine révision approche, réservez au… ». Après chaque passage, il envoie un lien vers sa fiche Google pour laisser un avis. Les clients n''ont plus à y penser, et reviennent au même garage.</p> </div> <h2>Les règles pour écrire à vos clients</h2> <p>La CNIL distingue les particuliers et les professionnels pour la prospection par e-mail et SMS :</p> <ul class="checklist"> <li><strong>Particuliers</strong> : il faut leur consentement avant de leur envoyer des offres. Exception : un client existant peut recevoir des offres pour des produits ou services similaires à ceux qu''il a déjà achetés chez vous, s''il en a été informé et pouvait refuser au moment de la collecte.</li> <li><strong>Professionnels</strong> : ils doivent être informés et pouvoir s''opposer, et le message doit concerner leur activité.</li> <li><strong>Dans tous les cas</strong> : chaque message permet de se désabonner simplement, et la demande est prise en compte.</li> <li><strong>Case à cocher</strong> : la CNIL recommande une case décochée par défaut ; la case pré-cochée est interdite pour recueillir le consentement.</li> </ul> <p>Un message de service (confirmation de commande, rappel d''un rendez-vous pris) n''est pas de la prospection, mais restez sobre : pas d''offre glissée dedans sans accord.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Les newsletters et campagnes d''e-mails envoyées chaque mois coûtent de 190 € à 490 € par mois selon le niveau. L''automatisation des relances et des séquences d''e-mails coûte à partir de 490 €.</p> <p><a href="/services#email-marketing" class="encadre-lien">Voir l''offre E-mail marketing</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Une carte de fidélité papier suffit-elle ?</h3> <p>Oui, pour un commerce de proximité, c''est simple et efficace. Elle ne vous permet pas de recontacter le client, en revanche : demandez en plus, avec son accord, un moyen de le joindre.</p> <h3>Puis-je envoyer mes offres à tous les clients de mon fichier ?</h3> <p>Pour des particuliers, seulement s''ils ont donné leur accord, ou s''il s''agit de produits similaires à ceux déjà achetés et qu''ils ont pu refuser au moment de la collecte. En cas de doute, demandez l''accord.</p> <h3>Combien de temps garder les coordonnées d''un ancien client ?</h3> <p>Selon le référentiel de la CNIL, les données d''un client utilisées pour la prospection peuvent être gardées pendant la relation commerciale, puis trois ans après sa fin.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique" target="_blank" rel="noopener">CNIL : la prospection commerciale par courrier électronique</a>.</li> <li><a href="https://www.cnil.fr/fr/questions-reponses-sur-les-referentiels-relatifs-la-gestion-des-activites-commerciales-et-des" target="_blank" rel="noopener">CNIL : questions-réponses sur les référentiels de gestion commerciale</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Fidéliser ses clients : leviers simples et règles', 'Garder le contact, remercier, récompenser, demander un avis : les leviers de fidélisation pour une TPE, et les règles de la CNIL pour écrire à ses clients.', 'fidéliser ses clients, fidélisation TPE, carte de fidélité, newsletter clients, prospection e-mail CNIL', '/assets/images/blog/fideliser-clients.webp', '/assets/images/blog/fideliser-clients.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('LinkedIn pour un dirigeant de TPE : profil, page et publications', 'linkedin-dirigeant', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Vos clients sont des entreprises ou des collectivités ? Un profil LinkedIn clair rassure avant le premier rendez-vous. Le profil en cinq étapes, le rythme de publication et la page entreprise.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>LinkedIn est utile si vos clients sont des entreprises, des collectivités ou des professionnels. Pour une clientèle de particuliers, d''autres réseaux passent souvent avant.</li> <li>Commencez par votre profil personnel : c''est lui qu''un client consulte quand il tape votre nom. La page entreprise, gratuite, vient en complément.</li> <li>Une publication par semaine, tirée de votre expérience de terrain, suffit pour être vu par votre réseau.</li> </ul> </div> <p>Un donneur d''ordre entend parler de vous, tape votre nom, et tombe sur un profil LinkedIn vide, avec une photo de vacances et un poste daté d''il y a cinq ans. Il n''appelle pas forcément. À l''inverse, un profil clair, qui montre ce que vous faites et pour qui, rassure avant même le premier rendez-vous.</p> <p>LinkedIn n''est pas réservé aux grandes entreprises ni aux chercheurs d''emploi. Pour un dirigeant de TPE qui travaille avec des professionnels, c''est souvent le réseau le plus rentable en temps. Voici l''essentiel, sans y passer ses soirées.</p> <h2>LinkedIn est-il fait pour vous ?</h2> <table class="table-article"> <thead><tr><th>Votre clientèle</th><th>Intérêt de LinkedIn</th></tr></thead> <tbody> <tr><td>Entreprises, commerces, professions libérales (B2B)</td><td>Fort : vos décideurs y sont, et y cherchent des prestataires</td></tr> <tr><td>Collectivités, associations, institutions</td><td>Fort : les acheteurs et élus y suivent l''actualité locale</td></tr> <tr><td>Particuliers (B2C)</td><td>Faible pour vendre, utile pour recruter ou trouver des partenaires</td></tr> </tbody> </table> <p>Si vos clients sont surtout des particuliers, comparez d''abord avec <a href="/blog/instagram-ou-facebook-reunion">Instagram et Facebook</a>.</p> <h2>Soigner son profil en 5 étapes</h2> <ol class="etapes"> <li><strong>Une photo professionnelle.</strong> Votre visage, cadré de près, sur un fond simple. LinkedIn indique dans son aide que les membres avec une photo de profil reçoivent jusqu''à deux fois plus de vues.</li> <li><strong>Un titre qui dit ce que vous faites et pour qui.</strong> Le titre se remplit avec votre poste, mais vous pouvez le réécrire : « Électricien pour les commerces et bureaux du Sud | Mise aux normes et dépannage » parle plus que « Gérant ».</li> <li><strong>Une bannière</strong> qui montre votre activité : une photo de chantier, votre équipe, vos coordonnées.</li> <li><strong>La section « À propos »</strong> en un ou deux paragraphes, comme le conseille LinkedIn : ce que vous faites, pour qui, ce qui vous distingue, et comment vous joindre.</li> <li><strong>Votre expérience à jour</strong>, avec l''entreprise actuelle reliée à sa page, et quelques réalisations en image ou en lien.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une gérante d''entreprise de nettoyage à Saint-Denis</p> <p>Son profil affichait « Gérante » et aucune publication. Elle change de photo, réécrit son titre en « Nettoyage de bureaux et commerces à Saint-Denis et Sainte-Marie | Équipe formée, interventions tôt le matin », et ajoute un paragraphe sur ses engagements. Chaque mardi, elle publie une courte observation de terrain : un conseil d''entretien, l''arrivée d''une nouvelle salariée, un chantier de fin de travaux.</p> </div> <h2>Publier sans y passer des heures</h2> <ul class="checklist"> <li><strong>Une publication par semaine</strong>, le même jour, prévue dans votre agenda.</li> <li><strong>Parlez de votre terrain</strong> : un problème réglé, une question de client, une leçon apprise. Le vécu intéresse plus qu''une plaquette commerciale.</li> <li><strong>Une image ou une courte vidéo</strong> faite au téléphone. Voir <a href="/blog/photos-telephone">réussir ses photos au téléphone</a>.</li> <li><strong>Répondez aux commentaires</strong> dans la journée, et commentez à votre tour les publications de vos clients et partenaires.</li> <li><strong>Invitez les personnes que vous rencontrez</strong> (salons, réunions, chantiers) avec un mot personnel.</li> </ul> <h2>Profil personnel ou page entreprise ?</h2> <p>Les deux se complètent. La page LinkedIn est gratuite et se crée depuis un compte personnel. Elle présente votre entreprise, vos produits et services et vos offres d''emploi, et rassure ceux qui vérifient. Commencez par votre profil, créez la page, puis partagez sur votre profil ce qu''elle publie : votre réseau personnel la découvrira ainsi.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Les contenus pour les réseaux sociaux sont préparés et planifiés chaque mois, à partir de 290 € par mois pour 8 publications. Le diagnostic gratuit permet de vérifier si LinkedIn est le bon réseau pour votre clientèle.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il un abonnement payant ?</h3> <p>Non. Le compte gratuit suffit pour soigner son profil, publier, créer une page entreprise et développer son réseau. Les abonnements payants servent surtout à la prospection intensive ou au recrutement.</p> <h3>Puis-je envoyer des messages de prospection sur LinkedIn ?</h3> <p>Oui, avec mesure : un message personnalisé, en rapport avec l''activité de la personne. Un message commercial copié-collé à des centaines de contacts abîme votre image plus qu''il ne rapporte.</p> <h3>Combien de temps avant d''avoir des résultats ?</h3> <p>Comptez quelques mois de publications régulières. LinkedIn travaille sur la confiance : on vous contacte souvent après vous avoir lu plusieurs fois.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.linkedin.com/help/linkedin/answer/a554351?lang=fr" target="_blank" rel="noopener">Assistance LinkedIn : créer un profil efficace sur LinkedIn</a>.</li> <li><a href="https://www.linkedin.com/help/linkedin/answer/a543852?lang=fr" target="_blank" rel="noopener">Assistance LinkedIn : créer une Page LinkedIn</a>.</li> <li><a href="https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique" target="_blank" rel="noopener">CNIL : la prospection commerciale par courrier électronique</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'LinkedIn pour un dirigeant de TPE : l''essentiel', 'LinkedIn est-il fait pour vous ? Soigner son profil en cinq étapes, publier une fois par semaine et créer la page entreprise : l''essentiel pour un dirigeant.', 'LinkedIn dirigeant, profil LinkedIn TPE, page entreprise LinkedIn, publier sur LinkedIn, LinkedIn B2B', '/assets/images/blog/linkedin-dirigeant.webp', '/assets/images/blog/linkedin-dirigeant.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;
